mapper.select:
SELECT time_bucket, COUNT(play_session.id) AS value FROM video_play_session play_session JOIN video_play_session filter ON play_session.id = filter.id AND filter.master_id = #{masterId}
AND filter.video_id IN
#{videoId}
RIGHT JOIN
( SELECT #{filter.start}::timestamp with time zone AS time_bucket UNION SELECT #{filter.end}::timestamp with time zone ) AS time_bucket ON play_session.create_time <= time_bucket
generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket ON play_session.create_time >= time_bucket AND play_session.create_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket ORDER BY time_bucket;

SELECT time_bucket, COUNT(DISTINCT play_session.user_id) AS value FROM video_play_session play_session JOIN video_play_session filter ON play_session.id = filter.id AND filter.master_id = #{masterId}
AND filter.video_id IN
#{videoId}
RIGHT JOIN
( SELECT #{filter.start}::timestamp with time zone AS time_bucket UNION SELECT #{filter.end}::timestamp with time zone ) AS time_bucket ON play_session.create_time <= time_bucket
generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket ON play_session.create_time >= time_bucket AND play_session.create_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket ORDER BY time_bucket;
